{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.uc_final_item_master AS WITH inventory_data AS ( SELECT \"Item SkuCode\" AS sku, SUM(COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0)) AS sellable_uc, SUM(COALESCE(NULLIF(TRIM(\"Bad Inventory\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Blocked\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Not Synced\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Not Found\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putaway Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putback Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Stock In Transfer\"), \'\')::INTEGER, 0)) AS total_uc FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-NORTH-TAURU\',\'SAPL_EMIZA\', \'SAPL-WH2\', \'SAPL-WH1\', \'JAYANAGAR_EBO\') and date = current_date GROUP BY 1 ), am AS ( SELECT DISTINCT sku_group AS keyuniq, sku_class, sales_last_15_days, sales_last_30_days, sales_last_7_days, natural_ros, CASE WHEN POSITION(\'-\' IN \"SKU_GROUP\") > 0 AND LEFT(\"SKU_GROUP\", 2) = \'SH\' THEN UPPER(SPLIT_PART(\"SKU_GROUP\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(SKU_GROUP, \'-\', 2)) WHEN POSITION(\'-\' IN \"SKU_GROUP\") > 0 THEN UPPER(SPLIT_PART(\"SKU_GROUP\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(SKU_GROUP, \'-\', 2)) ELSE UPPER(\"SKU_GROUP\") END AS sku_group1 FROM snitch_db.maplemonk.availability_master_v2 ), shopify_data AS ( SELECT * FROM ( SELECT MIN(publishedat::DATE) AS live_date, SPLIT_PART(ID, \'/\', -1) AS product_id, LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))) AS sku_group, VARIANT.value:sku::STRING AS sku, REPLACE(VARIANT.value:price::STRING, \'\"\', \'\')::INTEGER AS sf_sellingprice, REPLACE(VARIANT.value:compareAtPrice::STRING, \'\"\', \'\')::INTEGER AS acompare_at_price, CASE WHEN acompare_at_price > sf_sellingprice THEN acompare_at_price ELSE sf_sellingprice END AS SF_MRP, status, ROW_NUMBER() OVER (PARTITION BY VARIANT.value:sku::STRING ORDER BY MAX(IFNULL(publishedat::DATE, \'2021-01-01\')) DESC) AS rn FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql , TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT GROUP BY 2, 3, 4, 5, 6, 7,8 ) t QUALIFY rn = 1 ), logic_inventory AS ( SELECT addlitemcode AS sku, SUM(COALESCE((stock_qty), 0)) AS logic_total FROM snitch_db.maplemonk.LOgicerp23_24_get_stock_in_hand WHERE date = current_date GROUP BY 1 ), fk_mrp_data AS ( SELECT DISTINCT sku, NULLIF(mrp, \'\')::INTEGER AS mp_mrp FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'FLIPKART\' ), my_mrp_data AS ( SELECT DISTINCT SKU, UPPER(REGEXP_SUBSTR(SKU, \'^[^-]+-[^-]+\')) AS SKU_G, NULLIF(MRP, \'\')::INTEGER AS MP_MRP FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'MYNTRA\' ), aj_mrp_data AS ( SELECT DISTINCT sku, NULLIF(mrp, \'\')::INTEGER AS mp_mrp FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'AJIO\' ), am_mrp_data AS ( SELECT DISTINCT sku, NULLIF(mrp, \'\')::INTEGER AS mp_mrp FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'AMAZON\' ), nykaa_mrp_data AS ( SELECT DISTINCT sku, NULLIF(mrp, \'\')::INTEGER AS mp_mrp FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'NYKAA\' ), logic_item_master AS ( SELECT usercode as ean_logic, sku AS logic_sku, (COST_PRICE)::INTEGER AS logic_cp, (BASE_PRICE)::INTEGER AS logic_bp, (MRP)::INTEGER AS logic_mrp FROM SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER ), final AS ( SELECT UPPER(\"Category Code\") AS category_code, UPPER(\"Product Code\") AS sku, UPPER(name) AS name, UPPER(description) AS style, \"Scan Identifier\", UPPER(\"Requires Customization\") AS requires_customization, \"Length (mm)\", \"Width (mm)\", \"Height (mm)\", \"Weight (gms)\", ean, upc, isbn, color AS uc_color, size, brand, \"Item Detail Fields\", tags, \"Image Url\", \"Product Page Url\", \"Tax Type Code\", \"GST Tax Type Code\", COALESCE(NULLIF(TRIM(\"Base Price\"), \'\'), 0)::INTEGER AS base_price, COALESCE(NULLIF(TRIM(\"Cost Price\"), \'\'), 0)::INTEGER AS cost_price, tat, COALESCE(NULLIF(TRIM(mrp), \'\'), 0)::INTEGER AS MRP, updated, \"Category Name\" as category, enabled, type, \"Component Product Code\", \"Component Quantity\", \"Component Price\", \"HSN CODE\", \"Tax Calculation Type\", \"Batch Group\", \"GRN expiry tolerance (in days)\", \"Dispatch expiry tolerance (in days)\", \"Return expiry tolerance (in days)\", expirable, \"Determine Expiry From\", \"Shelf Life\", \"Expiry Date\", \"Sku Type\", fragile, \"Dangerous Good\", CASE WHEN \"Product Code\" LIKE \'%4C-%\' THEN UPPER(SPLIT_PART(\"Product Code\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(\"Product Code\", \'-\', 2)) || \'-\' || UPPER(SPLIT_PART(\"Product Code\", \'-\', 3)) WHEN POSITION(\'-\' IN \"Product Code\") > 0 AND LEFT(\"Product Code\", 2) = \'SH\' AND LENGTH(\"Product Code\") < 10 THEN UPPER(SPLIT_PART(\"Product Code\", \'-\', 1)) WHEN POSITION(\'-\' IN \"Product Code\") > 0 THEN UPPER(SPLIT_PART(\"Product Code\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(\"Product Code\", \'-\', 2)) ELSE UPPER(\"Product Code\") END AS skugroup, COALESCE(inv.sellable_uc, 0) AS sellable_uc, COALESCE(inv.total_uc, 0) AS total_uc, COALESCE(sim.logic_total, 0) AS total_logic, COALESCE(total_uc + total_logic, 0) AS total_universe, logic_mrp, logic_cp, logic_bp, div0(sf_sellingprice,COALESCE(NULLIF(TRIM(mrp), \'\'), 0)::INTEGER) as afterdisc, sf_mrp, ean_logic, product_id, CASE WHEN ifnull(sf_mrp,0)::int = 0 then \'MISSING ON SHOPIFY\' when ifnull(sf_mrp,0)::int = ifnull(nullif(mrp,\'\'),0)::int THEN \'CORRECT\' ELSE \'INCORRECT\' END AS SFxUC_MRP_MATCH, CASE WHEN logic_cp IS NULL THEN \'MISSING ON LOGIC\' WHEN IFNULL(logic_cp, 0) = IFNULL(cost_price, 0) THEN \'CORRECT\' ELSE \'INCORRECT\' END AS CP_MATCH, CASE WHEN logic_bp IS NULL THEN \'MISSING ON LOGIC\' WHEN IFNULL(logic_bp, 0) = IFNULL(base_price, 0) THEN \'CORRECT\' ELSE \'INCORRECT\' END AS BP_MATCH, CASE WHEN ifnull(logic_mrp,0)::int = 0 THEN \'MISSING ON LOGIC\' WHEN IFNULL(logic_mrp, 0)::int = IFNULL(nullif(MRP,\'\'), 0)::int THEN \'CORRECT\' ELSE \'INCORRECT\' END AS MRP_MATCH, CASE WHEN mrp_match LIKE \'%MISS%\' THEN \'MISSING\' WHEN cp_match LIKE \'%MISS%\' THEN \'MISSING\' WHEN bp_match LIKE \'%MISS%\' THEN \'MISSING\' WHEN mrp_match = \'INCORRECT\' THEN \'INCORRECT\' WHEN cp_match = \'INCORRECT\' THEN \'INCORRECT\' WHEN bp_match = \'INCORRECT\' THEN \'INCORRECT\' ELSE \'CORRECT\' END AS FINAL_CHECK_STATUS, (fk.mp_mrp) AS FK_MRP, (az.mp_mrp) AS AMAZON_MRP, (aj.mp_mrp) AS AJIO_MRP, (my.mp_mrp) AS MYNTRA_MRP, (ny.mp_mrp) AS NYKAA_MRP, CASE WHEN TRY_CAST(fk_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(fk_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(fk_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS FK_MRP_STATUS, CASE WHEN TRY_CAST(amazon_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(amazon_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(amazon_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS AMAZON_MRP_STATUS, CASE WHEN TRY_CAST(ajio_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(ajio_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(ajio_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS AJIO_MRP_STATUS, CASE WHEN TRY_CAST(nykaa_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(nykaa_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(nykaa_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS NYKAA_MRP_STATUS, CASE WHEN TRY_CAST(myntra_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(myntra_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(myntra_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS MYNTRA_MRP_STATUS, sd.status AS shopify_status, sku_class, sales_last_15_days, sales_last_30_days, sales_last_7_days, natural_ros, CASE WHEN SELLABLE_UC BETWEEN 1 AND 2 THEN \'01-02\' WHEN SELLABLE_UC BETWEEN 3 AND 5 THEN \'03-05\' WHEN SELLABLE_UC BETWEEN 6 AND 10 THEN \'06-10\' WHEN SELLABLE_UC BETWEEN 11 AND 98 THEN \'11-98\' WHEN SELLABLE_UC > 98 THEN \'98+++\' ELSE NULL END AS BRACKET FROM snitch_db.maplemonk.get_item_master im LEFT JOIN inventory_data inv ON UPPER(im.\"Product Code\") = UPPER(inv.sku) LEFT JOIN logic_item_master lim ON UPPER(im.\"Product Code\") = UPPER(logic_sku) LEFT JOIN logic_inventory sim ON UPPER(im.\"Product Code\") = UPPER(sim.sku) LEFT JOIN shopify_data sd ON UPPER(im.\"Product Code\") = UPPER(sd.sku) LEFT JOIN am_mrp_data az ON UPPER(im.\"Product Code\") = UPPER(az.sku) LEFT JOIN aj_mrp_data aj ON UPPER(im.\"Product Code\") = UPPER(aj.sku) LEFT JOIN my_mrp_data my ON UPPER(sku_group) = UPPER(my.sku_g) LEFT JOIN fk_mrp_data fk ON UPPER(im.\"Product Code\") = UPPER(fk.sku) LEFT JOIN nykaa_mrp_data ny ON UPPER(im.\"Product Code\") = UPPER(ny.sku) LEFT JOIN am ON TRIM(skugroup) = TRIM(am.sku_group1) ) SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY sku ORDER BY sku) AS rn FROM final ) t QUALIFY rn = 1 ORDER BY sku; create or replace table snitch_db.maplemonk.omni_inventory_check as with store_inv as ( select addlitemcode as sku, branch_name, sum(stock_qty) as total from snitch_db.maplemonk.LOgicerp23_24_get_stock_in_hand where date = current_date and sku not like \'%CB%\' group by 1,2 having total > 1 ), wh_inv as ( SELECT sku, skugroup, sum(sellable_uc) as sellable_uc, suM(total_uc) as total_uc FROM snitch_db.maplemonk.uc_final_item_master group by 1,2 ), final as ( select si.*,wi.sellable_uc, wi.total_uc, wi.skugroup from store_inv si left join wh_inv wi on si.sku = wi.sku ) select * from final where sellable_uc < 2 or sellable_uc is null and sku not like \'%CB%\' and sku not like \'%HANG%\' ;",
                    "transaction": true
